<?php
namespace App\Http\Controllers\Dashboard;
use App\Http\Controllers\Controller; use App\Http\Controllers\Dashboard\Concerns\RedirectsAfterSave; use Illuminate\Http\Request;
class ProfileController extends Controller { use RedirectsAfterSave; public function edit(Request $request) { return view('dashboard.profile', ['profile'=>$request->user()->participantProfile]); } public function update(Request $request) { $data=$request->validate(['salutation'=>['nullable','string','max:20'],'first_name'=>['required','string','max:255'],'last_name'=>['required','string','max:255'],'passport_full_name'=>['required','string','max:255'],'date_of_birth'=>['required','date'],'country'=>['required','string','max:255'],'address'=>['required','string','max:255'],'city'=>['required','string','max:255'],'postal_code'=>['required','string','max:50'],'id_document_type'=>['required','in:passport,id_card'],'id_document_number'=>['nullable','string','max:255'],'id_document_expires_at'=>['nullable','date'],'emergency_contact_name'=>['nullable','string','max:255'],'emergency_contact_phone'=>['nullable','string','max:255'],'medical_notes'=>['nullable','string'],'return_to'=>['nullable','url']]); $returnTo=$data['return_to']??null; unset($data['return_to']); $request->user()->participantProfile()->updateOrCreate(['user_id'=>$request->user()->id],$data); if ($returnTo) $request->merge(['return_to'=>$returnTo]); return $this->redirectAfterSave($request,'Profile saved'); } }
